function getNestedObject(obj, path) {
    // Split the path into individual keys
    const [keyPath] = path.split('.');

    // Split each key on '.' to get individual keys
    const keys = keyPath.split('.').map(k => k.trim());

    let currentObj = obj;

    for (const key of keys) {
        if (!currentObj || !key) continue; // Skip empty or undefined keys

        // Check if the current key exists in the current object
        if (!(key in currentObj)) break; // If not found, stop at this level

        currentObj = currentObj[key];
    }

